    const winners = [commit, release].filter(r => r.status === 'fulfilled');

    assert.equal(winners.length, 1);
    assert.ok([commit, release].find(r => r.status === 'rejected').reason instanceof OrderStateError);
    const expected = commit.status === 'fulfilled'
      ? { sku: DROP, stock: 8, reserved: 0, sold: 2 }
