describe('flash-sale replay', () => {
  it('a random mix of concurrent calls keeps every counter consistent with the orders', async () => {
    for (const seed of [1, 2, 3, 4, 5]) {
      const store = new JitterStore(seed);
      const rand = random(seed * 7919);
      let t = 0;
      const workers = Array.from({ length: 4 }, () =>
        new InventoryService({ store, now: () => t, reservationTtlMs: 50 }));
      const skus = ['a', 'b', 'c'];
      const added = { a: 20, b: 20, c: 20 };
      for (const sku of skus) {
        await workers[0].addStock(sku, added[sku]);
      }

      const pick = list => list[Math.floor(rand() * list.length)];
      const calls = [];
      for (let i = 0; i < 300; i++) {
        const svc = pick(workers);
        const orderId = `o${Math.floor(rand() * 60)}`;
        const roll = rand();
        t += 1;
        if (roll < 0.45) {
          const first = pick(skus);
          const items = [{ sku: first, qty: 1 + Math.floor(rand() * 3) }];
          const second = pick(skus);
          if (second !== first && rand() < 0.4) items.push({ sku: second, qty: 1 });
          calls.push(svc.reserve(orderId, items));
        } else if (roll < 0.65) {
          calls.push(svc.commit(orderId));
        } else if (roll < 0.8) {
          calls.push(svc.release(orderId));
        } else if (roll < 0.9) {
          const sku = pick(skus);
          added[sku] += 1;
          calls.push(svc.addStock(sku, 1));
        } else {
          calls.push(svc.expire());
        }
      }

      const results = await Promise.allSettled(calls);
      for (const r of results) {
        if (r.status === 'rejected') {
          const expected = r.reason instanceof InsufficientStockError
            || r.reason instanceof OrderStateError
            || r.reason instanceof UnknownOrderError;
          assert.ok(expected, `seed ${seed}: unexpected ${r.reason.stack}`);
        }
      }
      await assertConsistent(workers[0], store, added);
    }
  });
});

