'use strict';

// Reproductions of INC-5521. Each block maps to one symptom in ISSUE.md.

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  OrderStateError,
  UnknownOrderError,
  UnknownSkuError
} = require('../src');
const { seeded, JitterStore, random, assertConsistent } = require('./helpers');

const DROP = 'sneaker-limited';
const one = sku => [{ sku, qty: 1 }];

describe('oversold stock: 263 orders confirmed for 250 units', () => {
  it('concurrent reserves on one sku hold at most the units on hand', async () => {
    const svc = await seeded({ [DROP]: 250 });
    const results = await Promise.allSettled(
      Array.from({ length: 263 }, (_, i) => svc.reserve(`order-${i}`, one(DROP)))
    );
    const held = results.filter(r => r.status === 'fulfilled');
    const rejected = results.filter(r => r.status === 'rejected');

    assert.equal(held.length, 250);
    assert.equal(rejected.length, 13);
    for (const { reason } of rejected) {
      assert.ok(reason instanceof InsufficientStockError, reason.stack);
      assert.equal(reason.available, 0);
    }
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 250, reserved: 250, sold: 0 });

    await Promise.all(held.map(({ value }) => svc.commit(value.orderId)));
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 0, reserved: 0, sold: 250 });
  });

  it('40 workers, each with its own service on the shared store, do not oversell', async () => {
    const store = new Store();
    const workers = Array.from({ length: 40 }, () => new InventoryService({ store }));
    await workers[0].addStock(DROP, 250);

    const results = await Promise.allSettled(
      Array.from({ length: 263 }, (_, i) => workers[i % workers.length].reserve(`order-${i}`, one(DROP)))
    );

    assert.equal(results.filter(r => r.status === 'fulfilled').length, 250);
    assert.equal(await workers[7].available(DROP), 0);
  });

  it('a commit running alongside new reserves does not drop their holds', async () => {
    const svc = await seeded({ [DROP]: 10 });
    for (let i = 0; i < 5; i++) {
      await svc.reserve(`first-${i}`, one(DROP));
    }

    await Promise.all([
      ...Array.from({ length: 5 }, (_, i) => svc.commit(`first-${i}`)),
      ...Array.from({ length: 5 }, (_, i) => svc.reserve(`second-${i}`, one(DROP)))
    ]);

    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 5, reserved: 5, sold: 5 });
    await assert.rejects(svc.reserve('one-too-many', one(DROP)), InsufficientStockError);
  });

  it('concurrent addStock calls keep every unit', async () => {
    const svc = new InventoryService();
    await Promise.all(Array.from({ length: 50 }, () => svc.addStock(DROP, 2)));
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 100, reserved: 0, sold: 0 });
  });

  it('a restock during reserves is neither lost nor overwritten', async () => {
    const svc = await seeded({ [DROP]: 5 });
    await Promise.all([
      ...Array.from({ length: 5 }, (_, i) => svc.reserve(`o-${i}`, one(DROP))),
      svc.addStock(DROP, 5)
    ]);
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 10, reserved: 5, sold: 0 });
  });
});

describe('reserved went negative and did not recover', () => {
  it('expire() skips committed orders instead of releasing them again', async () => {
    let t = 0;
    const svc = new InventoryService({ now: () => t, reservationTtlMs: 1000 });
    await svc.addStock(DROP, 5);
    await svc.reserve('paid', [{ sku: DROP, qty: 2 }]);
    await svc.commit('paid');
    t = 5000;

    assert.deepEqual(await svc.expire(), []);
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 3, reserved: 0, sold: 2 });
    assert.equal((await svc.commit('paid')).status, 'committed');
  });

  it('expire() reports only the orders it released itself', async () => {
    let t = 0;
    const svc = new InventoryService({ now: () => t, reservationTtlMs: 1000 });
    await svc.addStock(DROP, 5);
    await svc.reserve('cancelled', one(DROP));
    await svc.release('cancelled');
    await svc.reserve('stale', one(DROP));
    t = 5000;

    assert.deepEqual(await svc.expire(), ['stale']);
    assert.deepEqual(await svc.expire(), []);
    assert.equal(await svc.available(DROP), 5);
  });

  it('release() of a committed order rejects with OrderStateError and changes nothing', async () => {
    const svc = await seeded({ [DROP]: 5 });
    await svc.reserve('paid', [{ sku: DROP, qty: 2 }]);
    await svc.commit('paid');

    await assert.rejects(svc.release('paid'), err => {
      assert.ok(err instanceof OrderStateError);
      assert.equal(err.status, 'committed');
      assert.equal(err.orderId, 'paid');
      return true;
    });
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 3, reserved: 0, sold: 2 });
    assert.equal((await svc.commit('paid')).status, 'committed');
  });

  it('concurrent release calls for one order return its units once', async () => {
    const svc = await seeded({ [DROP]: 10 });
    await svc.reserve('o1', [{ sku: DROP, qty: 3 }]);
    await svc.reserve('o2', [{ sku: DROP, qty: 3 }]);

    const results = await Promise.all([svc.release('o1'), svc.release('o1'), svc.release('o1')]);

    assert.ok(results.every(r => r.status === 'released'));
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 10, reserved: 3, sold: 0 });
  });

  it('expire() racing a customer cancel returns the units once', async () => {
    let t = 0;
    const svc = new InventoryService({ now: () => t, reservationTtlMs: 1000 });
    await svc.addStock(DROP, 10);
    await svc.reserve('o1', [{ sku: DROP, qty: 4 }]);
    await svc.reserve('fresh', [{ sku: DROP, qty: 1 }]);
    t = 5000;
    await svc.reserve('newer', [{ sku: DROP, qty: 1 }]);

    const [expired, cancelled] = await Promise.all([svc.expire(), svc.release('o1')]);

    assert.equal(cancelled.status, 'released');
    assert.ok(!expired.includes('newer'));
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 10, reserved: 1, sold: 0 });
  });

  it('two overlapping expire() runs release each order once', async () => {
    let t = 0;
    const svc = new InventoryService({ now: () => t, reservationTtlMs: 1000 });
    await svc.addStock(DROP, 10);
    for (let i = 0; i < 4; i++) {
      await svc.reserve(`o${i}`, [{ sku: DROP, qty: 2 }]);
    }
    t = 5000;

    const [a, b] = await Promise.all([svc.expire(), svc.expire()]);

    assert.deepEqual([...a, ...b].sort(), ['o0', 'o1', 'o2', 'o3']);
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 10, reserved: 0, sold: 0 });
  });
});

describe('a retried checkout held units twice for one order', () => {
  it('a retry that overlaps the original reserve holds the stock once', async () => {
    const svc = await seeded({ [DROP]: 10 });
    const items = [{ sku: DROP, qty: 2 }];

    const [first, retry] = await Promise.all([svc.reserve('o1', items), svc.reserve('o1', items)]);

    assert.deepEqual(first, { orderId: 'o1', status: 'reserved', items });
    assert.deepEqual(retry, first);
    assert.equal(await svc.available(DROP), 8);
    await svc.release('o1');
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 10, reserved: 0, sold: 0 });
  });

  it('many overlapping retries of a bundle hold each item once', async () => {
    const svc = await seeded({ shoe: 10, lace: 10 });
    const items = [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 2 }];

    await Promise.all(Array.from({ length: 8 }, () => svc.reserve('o1', items)));

    assert.equal(await svc.available('shoe'), 9);
    assert.equal(await svc.available('lace'), 8);
  });

  it('a retry that overlaps a failed reserve can still hold the stock', async () => {
    const svc = await seeded({ [DROP]: 2 });
    const [tooMany, retry] = await Promise.allSettled([
      svc.reserve('o1', [{ sku: DROP, qty: 5 }]),
      svc.reserve('o1', [{ sku: DROP, qty: 2 }])
    ]);

    assert.ok(tooMany.reason instanceof InsufficientStockError);
    assert.equal(retry.value.status, 'reserved');
    assert.equal(await svc.available(DROP), 0);
  });
});

describe('a rejected bundle left its other item held', () => {
  it('insufficient stock on one item holds none of the items', async () => {
    const svc = await seeded({ shoe: 5, lace: 1 });

    await assert.rejects(
      svc.reserve('bundle', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 2 }]),
      err => err instanceof InsufficientStockError && err.sku === 'lace' && err.available === 1
    );

    assert.deepEqual(await svc.snapshot('shoe'), { sku: 'shoe', stock: 5, reserved: 0, sold: 0 });
    assert.deepEqual(await svc.snapshot('lace'), { sku: 'lace', stock: 1, reserved: 0, sold: 0 });
    await assert.rejects(svc.release('bundle'), UnknownOrderError);
  });

  it('an unknown sku in a bundle holds none of the items', async () => {
    const svc = await seeded({ shoe: 5 });
    await assert.rejects(
      svc.reserve('bundle', [{ sku: 'shoe', qty: 1 }, { sku: 'ghost', qty: 1 }]),
      UnknownSkuError
    );
    assert.equal(await svc.available('shoe'), 5);
  });

  it('the first failing item in list order decides the error, as before', async () => {
    const svc = await seeded({ shoe: 1, lace: 5 });
    await assert.rejects(
      svc.reserve('bundle', [{ sku: 'shoe', qty: 2 }, { sku: 'ghost', qty: 1 }]),
      InsufficientStockError
    );
    await assert.rejects(
      svc.reserve('bundle', [{ sku: 'ghost', qty: 1 }, { sku: 'shoe', qty: 2 }]),
      UnknownSkuError
    );
  });

  it('a bundle that fails never causes a concurrent order for its in-stock item to fail', async () => {
    const svc = await seeded({ shoe: 1, lace: 1 });
    const [bundle, single] = await Promise.allSettled([
      svc.reserve('bundle', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 3 }]),
      svc.reserve('single', [{ sku: 'shoe', qty: 1 }])
    ]);

    assert.ok(bundle.reason instanceof InsufficientStockError);
    assert.equal(single.status, 'fulfilled');
    assert.deepEqual(await svc.snapshot('shoe'), { sku: 'shoe', stock: 1, reserved: 1, sold: 0 });
    assert.equal(await svc.available('lace'), 1);
  });

  it('bundles that list the same skus in opposite orders do not deadlock', async () => {
    const svc = await seeded({ shoe: 1, lace: 1 });
    const results = await Promise.allSettled([
      svc.reserve('ab', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }]),
      svc.reserve('ba', [{ sku: 'lace', qty: 1 }, { sku: 'shoe', qty: 1 }])
    ]);

    assert.equal(results.filter(r => r.status === 'fulfilled').length, 1);
    assert.ok(results.find(r => r.status === 'rejected').reason instanceof InsufficientStockError);
    assert.equal(await svc.available('shoe'), 0);
    assert.equal(await svc.available('lace'), 0);
  });
});

describe('sold counts higher than orders shipped', () => {
  it('concurrent commit retries count the sale once', async () => {
    const svc = await seeded({ [DROP]: 10 });
    await svc.reserve('o1', [{ sku: DROP, qty: 2 }]);

    const results = await Promise.all([svc.commit('o1'), svc.commit('o1'), svc.commit('o1')]);

    assert.ok(results.every(r => r.status === 'committed'));
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 8, reserved: 0, sold: 2 });
  });

  it('commit racing release settles on exactly one outcome', async () => {
    const svc = await seeded({ [DROP]: 10 });
    await svc.reserve('o1', [{ sku: DROP, qty: 2 }]);

    const [commit, release] = await Promise.allSettled([svc.commit('o1'), svc.release('o1')]);
    const winners = [commit, release].filter(r => r.status === 'fulfilled');

    assert.equal(winners.length, 1);
    assert.ok([commit, release].find(r => r.status === 'rejected').reason instanceof OrderStateError);
    const expected = commit.status === 'fulfilled'
      ? { sku: DROP, stock: 8, reserved: 0, sold: 2 }
      : { sku: DROP, stock: 10, reserved: 0, sold: 0 };
    assert.deepEqual(await svc.snapshot(DROP), expected);
  });

  it('commit racing expire() leaves an order that is either sold or released, not both', async () => {
    let t = 0;
    const svc = new InventoryService({ now: () => t, reservationTtlMs: 1000 });
    await svc.addStock(DROP, 10);
    await svc.reserve('o1', [{ sku: DROP, qty: 2 }]);
    t = 5000;

    const [commit, expired] = await Promise.allSettled([svc.commit('o1'), svc.expire()]);
    const snap = await svc.snapshot(DROP);

    if (commit.status === 'fulfilled') {
      assert.deepEqual(expired.value, []);
      assert.deepEqual(snap, { sku: DROP, stock: 8, reserved: 0, sold: 2 });
    } else {
      assert.ok(commit.reason instanceof OrderStateError);
      assert.deepEqual(expired.value, ['o1']);
      assert.deepEqual(snap, { sku: DROP, stock: 10, reserved: 0, sold: 0 });
    }
  });

  it('an expired sweep after the sale keeps committed orders committed', async () => {
    let t = 0;
    const svc = new InventoryService({ now: () => t, reservationTtlMs: 1000 });
    await svc.addStock(DROP, 3);
    await svc.reserve('shipped', one(DROP));
    await svc.commit('shipped');
    t = 5000;
    await svc.expire();

    await assert.rejects(svc.release('shipped'), OrderStateError);
    assert.equal((await svc.snapshot(DROP)).sold, 1);
    assert.equal((await svc.commit('shipped')).status, 'committed');
  });
});

describe('flash-sale replay', () => {
  it('a random mix of concurrent calls keeps every counter consistent with the orders', async () => {
    for (const seed of [1, 2, 3, 4, 5]) {
      const store = new JitterStore(seed);
      const rand = random(seed * 7919);
      let t = 0;
      const workers = Array.from({ length: 4 }, () =>
        new InventoryService({ store, now: () => t, reservationTtlMs: 50 }));
      const skus = ['a', 'b', 'c'];
      const added = { a: 20, b: 20, c: 20 };
      for (const sku of skus) {
        await workers[0].addStock(sku, added[sku]);
      }

      const pick = list => list[Math.floor(rand() * list.length)];
      const calls = [];
      for (let i = 0; i < 300; i++) {
        const svc = pick(workers);
        const orderId = `o${Math.floor(rand() * 60)}`;
        const roll = rand();
        t += 1;
        if (roll < 0.45) {
          const first = pick(skus);
          const items = [{ sku: first, qty: 1 + Math.floor(rand() * 3) }];
          const second = pick(skus);
          if (second !== first && rand() < 0.4) items.push({ sku: second, qty: 1 });
          calls.push(svc.reserve(orderId, items));
        } else if (roll < 0.65) {
          calls.push(svc.commit(orderId));
        } else if (roll < 0.8) {
          calls.push(svc.release(orderId));
        } else if (roll < 0.9) {
          const sku = pick(skus);
          added[sku] += 1;
          calls.push(svc.addStock(sku, 1));
        } else {
          calls.push(svc.expire());
        }
      }

      const results = await Promise.allSettled(calls);
      for (const r of results) {
        if (r.status === 'rejected') {
          const expected = r.reason instanceof InsufficientStockError
            || r.reason instanceof OrderStateError
            || r.reason instanceof UnknownOrderError;
          assert.ok(expected, `seed ${seed}: unexpected ${r.reason.stack}`);
        }
      }
      await assertConsistent(workers[0], store, added);
    }
  });
});

