'use strict';

// Reproductions of INC-5521. Each block maps to one symptom in ISSUE.md.

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  OrderStateError,
  UnknownOrderError,
  UnknownSkuError
} = require('../src');
const { seeded, JitterStore, random, assertConsistent } = require('./helpers');

const DROP = 'sneaker-limited';
const one = sku => [{ sku, qty: 1 }];

describe('oversold stock: 263 orders confirmed for 250 units', () => {
  it('concurrent reserves on one sku hold at most the units on hand', async () => {
    const svc = await seeded({ [DROP]: 250 });
    const results = await Promise.allSettled(
      Array.from({ length: 263 }, (_, i) => svc.reserve(`order-${i}`, one(DROP)))
    );
    const held = results.filter(r => r.status === 'fulfilled');
    const rejected = results.filter(r => r.status === 'rejected');

    assert.equal(held.length, 250);
    assert.equal(rejected.length, 13);
    for (const { reason } of rejected) {
      assert.ok(reason instanceof InsufficientStockError, reason.stack);
      assert.equal(reason.available, 0);
    }
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 250, reserved: 250, sold: 0 });

    await Promise.all(held.map(({ value }) => svc.commit(value.orderId)));
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 0, reserved: 0, sold: 250 });
  });

  it('40 workers, each with its own service on the shared store, do not oversell', async () => {
    const store = new Store();
    const workers = Array.from({ length: 40 }, () => new InventoryService({ store }));
    await workers[0].addStock(DROP, 250);

    const results = await Promise.allSettled(
      Array.from({ length: 263 }, (_, i) => workers[i % workers.length].reserve(`order-${i}`, one(DROP)))
    );

    assert.equal(results.filter(r => r.status === 'fulfilled').length, 250);
    assert.equal(await workers[7].available(DROP), 0);
  });

  it('a commit running alongside new reserves does not drop their holds', async () => {
    const svc = await seeded({ [DROP]: 10 });
    for (let i = 0; i < 5; i++) {
      await svc.reserve(`first-${i}`, one(DROP));
    }

    await Promise.all([
      ...Array.from({ length: 5 }, (_, i) => svc.commit(`first-${i}`)),
      ...Array.from({ length: 5 }, (_, i) => svc.reserve(`second-${i}`, one(DROP)))
    ]);

    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 5, reserved: 5, sold: 5 });
    await assert.rejects(svc.reserve('one-too-many', one(DROP)), InsufficientStockError);
  });

  it('concurrent addStock calls keep every unit', async () => {
    const svc = new InventoryService();
    await Promise.all(Array.from({ length: 50 }, () => svc.addStock(DROP, 2)));
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 100, reserved: 0, sold: 0 });
  });

  it('a restock during reserves is neither lost nor overwritten', async () => {
    const svc = await seeded({ [DROP]: 5 });
    await Promise.all([
      ...Array.from({ length: 5 }, (_, i) => svc.reserve(`o-${i}`, one(DROP))),
      svc.addStock(DROP, 5)
    ]);
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 10, reserved: 5, sold: 0 });
  });
});

describe('reserved went negative and did not recover', () => {
  it('expire() skips committed orders instead of releasing them again', async () => {
    let t = 0;
    const svc = new InventoryService({ now: () => t, reservationTtlMs: 1000 });
