    assert.equal(cancelled.status, 'released');
    assert.ok(!expired.includes('newer'));
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 10, reserved: 1, sold: 0 });
  });

  it('two overlapping expire() runs release each order once', async () => {
    let t = 0;
