    await svc.addStock(DROP, 10);
    for (let i = 0; i < 4; i++) {
      await svc.reserve(`o${i}`, [{ sku: DROP, qty: 2 }]);
    }
    t = 5000;

    const [a, b] = await Promise.all([svc.expire(), svc.expire()]);

    assert.deepEqual([...a, ...b].sort(), ['o0', 'o1', 'o2', 'o3']);
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 10, reserved: 0, sold: 0 });
  });
});

