'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { KeyedLock, locksFor } = require('../src/locks');
const { Store } = require('../src');
const { turns, within } = require('./helpers');

// A critical section that records how many runs are inside it at once.
function section(state, work = 3) {
  return async () => {
    state.inside += 1;
    state.peak = Math.max(state.peak, state.inside);
    await turns(work);
    state.inside -= 1;
  };
}

describe('KeyedLock', () => {
  it('runs callers of the same key one at a time', async () => {
    const locks = new KeyedLock();
    const state = { inside: 0, peak: 0 };
    await Promise.all(Array.from({ length: 10 }, () => locks.run(['a'], section(state))));
    assert.equal(state.peak, 1);
  });

  it('runs callers of different keys in parallel', async () => {
    const locks = new KeyedLock();
    const state = { inside: 0, peak: 0 };
    await Promise.all(Array.from({ length: 10 }, (_, i) => locks.run([`k${i}`], section(state))));
    assert.equal(state.peak, 10);
  });

  it('grants a key to waiters in arrival order', async () => {
    const locks = new KeyedLock();
    const order = [];
    await Promise.all([1, 2, 3, 4].map(n => locks.run(['a'], async () => {
      await turns(1);
      order.push(n);
    })));
    assert.deepEqual(order, [1, 2, 3, 4]);
  });

  it('does not deadlock callers that list shared keys in opposite orders', async () => {
    const locks = new KeyedLock();
    const state = { inside: 0, peak: 0 };
    await within(Promise.all([
      locks.run(['a', 'b', 'c'], section(state)),
      locks.run(['c', 'b', 'a'], section(state)),
      locks.run(['b', 'a'], section(state))
    ]), 1000, 'overlapping multi-key runs');
    assert.equal(state.peak, 1);
  });

  it('returns what the callback returns', async () => {
    const locks = new KeyedLock();
    assert.equal(await locks.run(['a'], async () => 42), 42);
    assert.equal(await locks.run(['a'], () => 'sync'), 'sync');
  });

  it('releases every key and rethrows when the callback rejects', async () => {
    const locks = new KeyedLock();
    const boom = new Error('boom');
    await assert.rejects(locks.run(['a', 'b'], async () => { throw boom; }), err => err === boom);
    assert.equal(locks.size, 0);
    assert.equal(await locks.run(['a', 'b'], () => 'free'), 'free');
  });

  it('releases the keys when the callback throws synchronously', async () => {
    const locks = new KeyedLock();
    await assert.rejects(locks.run(['a'], () => { throw new TypeError('sync'); }), TypeError);
    assert.equal(locks.size, 0);
  });

  it('drops a key once nothing holds or waits for it', async () => {
    const locks = new KeyedLock();
    const pending = Promise.all(Array.from({ length: 5 }, () => locks.run(['a', 'b'], () => turns(1))));
    await turns(1);
    assert.equal(locks.size, 2);
    await pending;
    assert.equal(locks.size, 0);
