    const locks = new KeyedLock();
    const result = await within(locks.run(['a', 'a', 'b', 'a'], () => 'ok'), 1000, 'duplicate keys');
    assert.equal(result, 'ok');
  });

  it('runs the callback straight away for an empty key list', async () => {
    const locks = new KeyedLock();
    assert.equal(await locks.run([], () => 'none'), 'none');
    assert.equal(locks.size, 0);
  });

  it('orders unicode keys consistently, so they cannot deadlock either', async () => {
    const locks = new KeyedLock();
    const state = { inside: 0, peak: 0 };
    await within(Promise.all([
      locks.run(['sku:👟', 'sku:é', 'sku:z'], section(state)),
