'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  InsufficientStockError,
  OrderStateError,
  UnknownOrderError,
  UnknownSkuError,
  ValidationError
} = require('../src');
const { locksFor } = require('../src/locks');
const {
  seeded,
  GatedStore,
  CountingStore,
  FailingStore,
  JitterStore,
  turns,
  settle,
  within
} = require('./helpers');

const LIMIT_MS = 1000;

describe('calls that share no sku and no order do not wait for each other', () => {
  async function stalledReserve() {
    const store = new GatedStore();
    const svc = new InventoryService({ store });
    await svc.addStock('hot', 5);
    await svc.addStock('cold', 5);
    const gate = store.gate('sku:hot', ['set']);
    const stalled = settle(svc.reserve('stuck', [{ sku: 'hot', qty: 1 }]));
    await gate.reached;
    return { store, svc, gate, stalled };
  }

  it('a reserve on another sku completes while one sku is stalled mid-reserve', async () => {
    const { svc, gate, stalled } = await stalledReserve();
    const other = await within(svc.reserve('free', [{ sku: 'cold', qty: 2 }]), LIMIT_MS, 'reserve on cold');
    assert.equal(other.status, 'reserved');
    gate.open();
    assert.equal((await stalled).status, 'fulfilled');
  });

  it('addStock, commit and release on other keys complete while one sku is stalled', async () => {
    const { svc, gate, stalled } = await stalledReserve();
    await within((async () => {
      await svc.addStock('cold', 1);
      await svc.addStock('brand-new', 1);
      await svc.reserve('a', [{ sku: 'cold', qty: 1 }]);
      await svc.reserve('b', [{ sku: 'cold', qty: 1 }]);
      await svc.commit('a');
      await svc.release('b');
    })(), LIMIT_MS, 'calls on cold');
    assert.deepEqual(await svc.snapshot('cold'), { sku: 'cold', stock: 5, reserved: 0, sold: 1 });
    gate.open();
    await stalled;
  });

  it('reads of a stalled sku do not wait for its lock', async () => {
    const { svc, gate, stalled } = await stalledReserve();
    assert.equal(await within(svc.available('hot'), LIMIT_MS, 'available(hot)'), 5);
    gate.open();
    await stalled;
    assert.equal(await svc.available('hot'), 4);
  });

  it('a call on the stalled sku does wait, then goes through', async () => {
    const { svc, gate, stalled } = await stalledReserve();
    let settled = false;
    const same = svc.reserve('next', [{ sku: 'hot', qty: 1 }]).finally(() => { settled = true; });
    await turns(20);
    assert.equal(settled, false);
    gate.open();
    await stalled;
    assert.equal((await same).status, 'reserved');
    assert.equal(await svc.available('hot'), 3);
  });

  it('a commit of another order completes while one order is stalled', async () => {
    const store = new GatedStore();
    const svc = new InventoryService({ store });
    await svc.addStock('shared', 5);
    await svc.reserve('o1', [{ sku: 'shared', qty: 1 }]);
    await svc.reserve('o2', [{ sku: 'shared', qty: 1 }]);
    // o1's commit stalls writing its order record, after its sku writes.
    const gate = store.gate('order:o1', ['set']);
    const stalled = settle(svc.commit('o1'));
    await gate.reached;

    const other = await within(svc.commit('o2'), LIMIT_MS, 'commit o2');
    assert.equal(other.status, 'committed');
    gate.open();
    assert.equal((await stalled).value.status, 'committed');
    assert.deepEqual(await svc.snapshot('shared'), { sku: 'shared', stock: 3, reserved: 0, sold: 2 });
  });

  it('expire() does not wait for a stalled order it has no reason to release', async () => {
    let t = 0;
    const store = new GatedStore();
    const svc = new InventoryService({ store, now: () => t, reservationTtlMs: 1000 });
    await svc.addStock('a', 5);
    await svc.reserve('old', [{ sku: 'a', qty: 1 }]);
    t = 5000;
    await svc.reserve('fresh', [{ sku: 'a', qty: 1 }]);
    const gate = store.gate('order:fresh', ['set']);
    const stalled = settle(svc.commit('fresh'));
    await gate.reached;

    assert.deepEqual(await within(svc.expire(), LIMIT_MS, 'expire'), ['old']);
    gate.open();
    await stalled;
  });

  it('reserves on distinct skus are all in flight at the store at once', async () => {
    const store = new CountingStore();
    const svc = new InventoryService({ store });
    const skus = Array.from({ length: 20 }, (_, i) => `sku-${i}`);
    await Promise.all(skus.map(sku => svc.addStock(sku, 1)));
    store.peak = 0;

    await Promise.all(skus.map((sku, i) => svc.reserve(`o${i}`, [{ sku, qty: 1 }])));

    assert.equal(store.peak, skus.length);
  });
});

describe('store failures leave the counters as they were', () => {
  it('a failed sku write rolls back the bundle items already written', async () => {
    const store = new FailingStore();
    const svc = new InventoryService({ store });
    await svc.addStock('shoe', 5);
    await svc.addStock('lace', 5);
    const injected = store.failNext('set', 'sku:lace');

    await assert.rejects(
      svc.reserve('bundle', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }]),
      err => err === injected
    );

    assert.equal(await svc.available('shoe'), 5);
    assert.equal(await svc.available('lace'), 5);
    await assert.rejects(svc.commit('bundle'), UnknownOrderError);
    assert.equal(locksFor(store).size, 0);
    assert.equal((await svc.reserve('bundle', [{ sku: 'shoe', qty: 1 }])).status, 'reserved');
  });

  it('a failed order write on reserve returns the held units', async () => {
    const store = new FailingStore();
    const svc = new InventoryService({ store });
    await svc.addStock('shoe', 5);
    store.failNext('set', 'order:o1');

    await assert.rejects(svc.reserve('o1', [{ sku: 'shoe', qty: 2 }]), /injected set failure/);

    assert.deepEqual(await svc.snapshot('shoe'), { sku: 'shoe', stock: 5, reserved: 0, sold: 0 });
    assert.equal((await svc.reserve('o1', [{ sku: 'shoe', qty: 2 }])).status, 'reserved');
    assert.equal(await svc.available('shoe'), 3);
  });

  it('a failed order write on commit leaves the order reserved and the units held', async () => {
    const store = new FailingStore();
    const svc = new InventoryService({ store });
    await svc.addStock('shoe', 5);
    await svc.reserve('o1', [{ sku: 'shoe', qty: 2 }]);
    store.failNext('set', 'order:o1');

    await assert.rejects(svc.commit('o1'), /injected set failure/);

    assert.deepEqual(await svc.snapshot('shoe'), { sku: 'shoe', stock: 5, reserved: 2, sold: 0 });
    assert.equal((await svc.commit('o1')).status, 'committed');
    assert.deepEqual(await svc.snapshot('shoe'), { sku: 'shoe', stock: 3, reserved: 0, sold: 2 });
  });

  it('a failed sku write on release keeps the hold and the order reserved', async () => {
    const store = new FailingStore();
    const svc = new InventoryService({ store });
    await svc.addStock('shoe', 5);
    await svc.addStock('lace', 5);
    await svc.reserve('o1', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }]);
    store.failNext('set', 'sku:shoe');

    await assert.rejects(svc.release('o1'), /injected set failure/);

    assert.equal(await svc.available('shoe'), 4);
    assert.equal(await svc.available('lace'), 4);
    assert.equal((await svc.release('o1')).status, 'released');
  });

  it('a rollback that also fails is reported with the keys to check', async () => {
    const store = new FailingStore();
    const svc = new InventoryService({ store });
    await svc.addStock('shoe', 5);
    await svc.addStock('lace', 5);
    const first = store.failNext('set', 'sku:lace');
    const second = store.failNext('set', 'sku:lace');

    await assert.rejects(svc.reserve('o1', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }]), err => {
      assert.ok(err instanceof AggregateError);
      assert.deepEqual(err.errors, [first, second]);
      assert.match(err.message, /sku:lace/);
      assert.doesNotMatch(err.message, /sku:shoe/);
      return true;
    });
    assert.equal(await svc.available('shoe'), 5);
    assert.equal(locksFor(store).size, 0);
  });

  it('a failed read rejects the call and frees its locks', async () => {
    const store = new FailingStore();
    const svc = new InventoryService({ store });
    await svc.addStock('shoe', 5);
    store.failNext('get', 'sku:shoe');

    await assert.rejects(svc.reserve('o1', [{ sku: 'shoe', qty: 1 }]), /injected get failure/);

    assert.equal(locksFor(store).size, 0);
    assert.equal((await svc.reserve('o1', [{ sku: 'shoe', qty: 1 }])).status, 'reserved');
  });
});

describe('boundaries and input handling', () => {
  it('reserving exactly the available units succeeds and one more fails', async () => {
    const svc = await seeded({ widget: 3 });
    await svc.reserve('all', [{ sku: 'widget', qty: 3 }]);
    await assert.rejects(
      svc.reserve('extra', [{ sku: 'widget', qty: 1 }]),
      err => err instanceof InsufficientStockError && err.requested === 1 && err.available === 0
    );
  });

  it('expire() releases an order only once it is strictly older than the TTL', async () => {
    let t = 1000;
    const svc = new InventoryService({ now: () => t, reservationTtlMs: 500 });
    await svc.addStock('widget', 1);
    await svc.reserve('o1', [{ sku: 'widget', qty: 1 }]);
    t = 1500;
    assert.deepEqual(await svc.expire(), []);
    t = 1501;
    assert.deepEqual(await svc.expire(), ['o1']);
  });

  it('expire() on an empty store returns an empty list', async () => {
    assert.deepEqual(await new InventoryService().expire(), []);
  });

  it('commit and release of an unknown order reject with UnknownOrderError', async () => {
    const svc = await seeded({ widget: 1 });
    await assert.rejects(svc.commit('missing'), UnknownOrderError);
    await assert.rejects(svc.release('missing'), UnknownOrderError);
  });

  it('a retry with different items returns the original reservation', async () => {
    const svc = await seeded({ widget: 5, gadget: 5 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 1 }]);
    const retry = await svc.reserve('o1', [{ sku: 'gadget', qty: 4 }]);
    assert.deepEqual(retry.items, [{ sku: 'widget', qty: 1 }]);
    assert.equal(await svc.available('gadget'), 5);
  });

  it('bad arguments reject with ValidationError and take no locks', async () => {
    const store = new FailingStore();
    const svc = new InventoryService({ store });
    await svc.addStock('widget', 5);
    const bad = [
      svc.addStock('', 1),
      svc.addStock('widget', 1.5),
      svc.addStock('widget', -1),
      svc.reserve('  ', [{ sku: 'widget', qty: 1 }]),
      svc.reserve('o1', 'widget'),
      svc.reserve('o1', [null]),
      svc.reserve('o1', [{ sku: 'widget', qty: 0 }]),
      svc.reserve('o1', [{ sku: 'widget', qty: 1 }, { sku: 'widget', qty: 2 }]),
      svc.commit(undefined),
      svc.release(42),
      svc.available(null)
    ];
    for (const call of bad) {
      await assert.rejects(call, ValidationError);
    }
    assert.equal(locksFor(store).size, 0);
    assert.equal(await svc.available('widget'), 5);
  });

  it('the constructor rejects a store without get, set and keys', () => {
    for (const store of [null, 42, {}, { get() {}, set() {} }]) {
      assert.throws(() => new InventoryService({ store }), ValidationError);
    }
  });

  it('reserve neither mutates the caller\'s items nor sees later changes to them', async () => {
    const svc = await seeded({ widget: 5, gadget: 5 });
    const items = [{ sku: 'widget', qty: 1 }];
    const copy = structuredClone(items);
    const pending = svc.reserve('o1', items);
    items[0].qty = 4;
    items.push({ sku: 'gadget', qty: 1 });

    const reservation = await pending;

    assert.deepEqual(reservation.items, copy);
    assert.equal(await svc.available('widget'), 4);
    assert.equal(await svc.available('gadget'), 5);
    items.length = 0;
    reservation.items[0].qty = 99;
    assert.deepEqual((await svc.reserve('o1', copy)).items, copy);
  });

  it('works with a store that hands back its own objects instead of copies', async () => {
    const store = new JitterStore(11);
    const svc = new InventoryService({ store });
    await svc.addStock('widget', 5);
    const stored = await store.get('sku:widget');
    const seen = { ...stored };

    await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
    await svc.commit('o1');

    assert.deepEqual(stored, seen);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 3, reserved: 0, sold: 2 });
  });

  it('handles unicode skus and order ids', async () => {
    const svc = await seeded({ 'スニーカー': 2, '👟-limited': 1 });
    await svc.reserve('注文-1', [{ sku: 'スニーカー', qty: 2 }, { sku: '👟-limited', qty: 1 }]);
    await svc.commit('注文-1');
    assert.deepEqual(await svc.snapshot('👟-limited'), { sku: '👟-limited', stock: 0, reserved: 0, sold: 1 });
    await assert.rejects(svc.reserve('注文-2', [{ sku: 'スニーカー', qty: 1 }]), InsufficientStockError);
    await assert.rejects(svc.snapshot('👟'), UnknownSkuError);
  });

  it('the lock table is empty after a burst of mixed calls, failures included', async () => {
    const store = new JitterStore(3);
    const svc = new InventoryService({ store, reservationTtlMs: 0 });
    await svc.addStock('a', 3);
    await Promise.allSettled([
      ...Array.from({ length: 10 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'a', qty: 1 }])),
      ...Array.from({ length: 10 }, (_, i) => svc.commit(`o${i}`)),
      svc.release('o1'),
      svc.reserve('bad', [{ sku: 'missing', qty: 1 }]),
      svc.expire()
    ]);
    assert.equal(locksFor(store).size, 0);
